// NORMALIZE — flatten the mock WhatsApp inbound payload to { phone, text, name }.
// SWAP-POINT (WHATSAPP INBOUND): the real shape comes from the Meta WhatsApp
// Cloud API webhook: entry[].changes[].value.messages[] + .contacts[].profile.name.
// Mock payload this scaffold expects (see the webhook node's sticky note):
//   { "from": "+15551234567", "text": "Hi, do you do balayage?", "profile_name": "Maria" }
const body = $json.body ?? $json;
const msg  = (body.messages && body.messages[0]) ? body.messages[0] : body;
const phone = (body.from ?? msg.from ?? body.phone ?? '').toString().trim();
const text  = ((msg.text && msg.text.body) ?? body.text ?? '').toString().trim();
const name  = body.profile_name
  ?? (body.contacts && body.contacts[0] && body.contacts[0].profile && body.contacts[0].profile.name)
  ?? body.name ?? null;
return [{ json: { phone, text, name } }];

// BUILD PROMPT — persona + services (from DB) + recent history + the new message.
// n8n keeps every node's output addressable, so we pull context by node name.
const norm = $('Normalize inbound').first().json;                 // { phone, text, name }
const recent = $('Load recent messages (context)').all()          // newest-first rows
  .map(i => i.json).reverse();                                     // -> chronological

// SERVICES (from DB): production wires a `SELECT * FROM services` Postgres read into
// this node (a documented extension point). Embedded here from the seed so the
// scaffold is self-contained and the prompt is realistic.
const services = [
  { name: "Women's Haircut", price: 45,  duration_min: 60 },
  { name: "Men's Haircut",   price: 30,  duration_min: 45 },
  { name: "Blow-Dry & Style",price: 40,  duration_min: 45 },
  { name: "Full Color",      price: 110, duration_min: 90 },
  { name: "Balayage",        price: 180, duration_min: 150 },
  { name: "Root Touch-Up",   price: 75,  duration_min: 60 },
  { name: "Manicure",        price: 35,  duration_min: 40 },
  { name: "Pedicure",        price: 50,  duration_min: 55 }
];

const persona = [
  'You are the friendly, concise front-desk receptionist for "SC Salon".',
  'Use ONLY the services and prices listed below. Never invent a service, a price, or availability.',
  'To capture a booking you must collect: service, preferred time, name, and email.',
  'When you have all four, set booking.ready = true. Otherwise ask for exactly one missing item.',
  'Be warm and brief — 1 to 3 short sentences.'
].join('\n');

const menu = services.map(s => `- ${s.name}: $${s.price} (${s.duration_min} min)`).join('\n');
const history = recent.map(m => `${m.role === 'user' ? 'Customer' : 'Receptionist'}: ${m.text}`).join('\n');

const prompt = [
  persona,
  '\nSERVICES:\n' + menu,
  history ? '\nCONVERSATION SO FAR:\n' + history : '',
  '\nNEW MESSAGE from ' + (norm.name || 'the customer') + ':\n' + norm.text,
  '\nRespond with JSON ONLY, in exactly this shape:',
  '{"reply":"...","intent":"faq|services|booking|smalltalk|other",' +
  '"booking":{"service":null,"requested_time":null,"name":null,"email":null,"ready":false},"missing":[]}'
].join('\n');

return [{ json: { prompt, phone: norm.phone } }];

// PARSE + FALLBACK — read the Ollama response, parse strict JSON. On ANY failure
// (bad JSON, missing fields, model hiccup) synthesize a safe reply so the flow
// never breaks and the customer always gets an answer.
const phone = $('Build prompt').first().json.phone;
let raw = $json.response ?? $json.data ?? ($json.body && $json.body.response) ?? '';
let out;
try {
  out = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (!out || typeof out.reply !== 'string') throw new Error('missing reply');
} catch (e) {
  out = {
    reply: "Thanks for reaching out! I'd love to help — which service are you interested in?",
    intent: 'other',
    booking: { service: null, requested_time: null, name: null, email: null, ready: false },
    missing: ['service'],
    _fallback: true
  };
}
const b = out.booking || {};
return [{ json: {
  phone,
  reply: out.reply,
  intent: out.intent ?? 'other',
  booking_ready: b.ready === true,
  service: b.service ?? null,
  requested_time: b.requested_time ?? null,
  cust_name: b.name ?? null,
  cust_email: b.email ?? null,
  missing: Array.isArray(out.missing) ? out.missing : [],
  fallback: out._fallback === true
}}];
